import type { Metadata } from "next";
import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import ScrollReveal from "@/components/ScrollReveal";
import EnquiryModal from "@/components/EnquiryModal";
import { site } from "@/data";
// Fonts from site.json (theme.fonts), generated by scripts/fonts.mjs.
import { fontVariables } from "./fonts.generated";
import "./globals.css";

export const metadata: Metadata = {
  title: site.navbar.seo.title,
  description: site.navbar.seo.description,
};

// Colours come from site.json (theme.colors) and override the globals.css defaults; invalid values are skipped.
const isHex = (v: string) => /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(v);
const themeCss = `:root{${Object.entries(site.theme.colors)
  .filter(([, v]) => isHex(v))
  .map(([k, v]) => `--color-${k}:${v}`)
  .join(";")}}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      data-scroll-behavior="smooth"
      // Root font size: 16px, and from 1024px up it follows the 1440px design (1rem = 1/90 of the screen, at most 16px),
      // so 1024px shows exactly the 1440px layout, only smaller. Every size on the page is in rem, so it all scales together.
      // Header and footer links scroll smoothly to their section on this one page.
      // Tailwind v4 leaves buttons on the default cursor, so everything clickable gets the pointer
      // (in :where(), so a cursor-* class on the element still wins).
      className={`${fontVariables} h-full text-[16px] lg:text-[length:min(16px,calc(100vw/90))] scroll-smooth antialiased motion-reduce:scroll-auto motion-reduce:**:duration-[0.01ms]! [:where(&)_:where(a[href],button:not(:disabled),select,[role=button],summary)]:cursor-pointer`}
    >
      <head>
        <style dangerouslySetInnerHTML={{ __html: themeCss }} />
      </head>
      <body className="min-h-full bg-backdrop font-sans text-body selection:bg-maroon selection:text-white">
        {/* Every call-to-action on the page opens the one enquiry form in a modal (components/EnquiryModal) */}
        <EnquiryModal>
          {/*
            The whole site sits in one frame, at most 1920px wide and centred. Up to 1920px it fills the screen, so
            nothing changes; on wider screens or when the browser is zoomed out the page stays in the middle with
            equal space on both sides instead of stretching.
            --section-gap is the one space above and below every section (and inside the footer), the same on
            phones, tablets and desktops: 5rem (80px; on desktop it scales with the page, see the font size above).
          */}
          <div className="mx-auto min-h-screen w-full max-w-[1920px] overflow-x-clip bg-page [--section-gap:5rem]">
            <Navbar data={site.navbar} />
            <main>
              {children}
              <ScrollReveal />
            </main>
            <Footer data={site.footer} />
          </div>
        </EnquiryModal>
      </body>
    </html>
  );
}
